create extension if not exists pgcrypto;
create table trucks(id uuid primary key default gen_random_uuid(),name text not null,mileage integer default 0,created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'employee' check(role in ('owner','manager','employee')),created_at timestamptz default now());
create table equipment(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,name text not null,critical boolean default false,status text default 'OK',created_at timestamptz default now());
create table inspections(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,user_id uuid references auth.users(id),item text not null,result text not null check(result in ('PASS','FAIL')),critical boolean default false,notes text,created_at timestamptz default now());
create table temperature_logs(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,user_id uuid references auth.users(id),location text not null,temp_f numeric not null,notes text,created_at timestamptz default now());
create table maintenance(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,title text not null,due_date date,status text default 'Open',notes text,created_at timestamptz default now());
create table events(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,name text not null,event_date date,location text,notes text,created_at timestamptz default now());
create table incidents(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,user_id uuid references auth.users(id),title text not null,severity text,description text,action_taken text,created_at timestamptz default now());
create table documents(id uuid primary key default gen_random_uuid(),truck_id uuid references trucks(id) on delete cascade,name text not null,expires_on date,reference text,storage_path text,created_at timestamptz default now());
